sys_script_client.script:
function onLoad() {
    // Set Student to current logged-in user
    g_form.setValue('student', g_user.userID);

    // Set Registration Date to current date/time
    var now = new Date();
    var dateTime = now.getFullYear() + '-' +
        String(now.getMonth() + 1).padStart(2, '0') + '-' +
        String(now.getDate()).padStart(2, '0') + ' ' +
        String(now.getHours()).padStart(2, '0') + ':' +
        String(now.getMinutes()).padStart(2, '0') + ':' +
        String(now.getSeconds()).padStart(2, '0');

    g_form.setValue('registration_date', dateTime);

    // Set Status to Pending
    g_form.setValue('status', 'pending');

    // Make these fields read-only
    g_form.setReadOnly('student', true);
    g_form.setReadOnly('registration_date', true);
    g_form.setReadOnly('status', true);
}
